	// They are set by the "off" word, cleared by the "on" word, by a fresh
	// tracking start (updatePaused), and they don't matter while the
	// checkbox itself is on (the key-binding path owns the gesture then).
	let mouthClickSuppressed = false;
	let blinkClickSuppressed = false;
